package com.portfolio.features.project.service; import com.portfolio.common.exception.*; import com.portfolio.features.portfolio.service.PortfolioAccessService; import com.portfolio.features.project.dto.ProjectRequest; import com.portfolio.features.project.entity.*; import com.portfolio.features.project.repository.ProjectRepository; import com.portfolio.features.user.entity.AppUser; import java.util.*; import lombok.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; @Service @RequiredArgsConstructor public class ProjectService {private final ProjectRepository repo;private final PortfolioAccessService access;@Transactional(readOnly=true) public List<Project> list(AppUser u){return repo.findByPortfolioIdOrderBySortOrderAscTitleAsc(access.mine(u).getId());}@Transactional(readOnly=true) public Project get(AppUser u,UUID id){return owned(u,id);}@Transactional public Project create(AppUser u,ProjectRequest r){var p=access.mine(u);Project project=new Project();project.setPortfolio(p);apply(project,r,p.getId(),null);return repo.save(project);}@Transactional public Project update(AppUser u,UUID id,ProjectRequest r){Project p=owned(u,id);apply(p,r,p.getPortfolio().getId(),id);return p;}@Transactional public void delete(AppUser u,UUID id){repo.delete(owned(u,id));}private Project owned(AppUser u,UUID id){Project p=repo.findById(id).orElseThrow(()->new NotFoundException("Project not found."));access.owned(u,p.getPortfolio().getId());return p;}private void apply(Project p,ProjectRequest r,UUID portfolioId,UUID id){p.setTitle(r.title().trim());String slug=slug(r.slug()==null||r.slug().isBlank()?r.title():r.slug());if(repo.existsByPortfolioIdAndSlug(portfolioId,slug)&& (id==null||!slug.equals(p.getSlug()))) throw new ConflictException("Project slug is already in use.");p.setSlug(slug);p.setShortDescription(r.shortDescription());p.setDescription(r.description());p.setThumbnailUrl(r.thumbnailUrl());p.setGithubUrl(r.githubUrl());p.setDemoUrl(r.demoUrl());p.setFeatured(r.featured());p.setSortOrder(r.sortOrder());p.getTechnologies().clear();if(r.technologies()!=null){Set<String> values=new LinkedHashSet<>();for(String t:r.technologies())if(t!=null&&!t.isBlank())values.add(t.trim());int order=0;for(String t:values){ProjectTechnology pt=new ProjectTechnology();pt.setProject(p);pt.setTechnology(t);pt.setSortOrder(order++);p.getTechnologies().add(pt);}}}private String slug(String value){return value.toLowerCase().trim().replaceAll("[^a-z0-9]+","-").replaceAll("(^-|-$)","");}}
